const AgentUtils = {
    safeLog: (msg) => {
        if (this && this.logger) {
            this.logger.log(`[Agent] ${msg}`);
        } else {
            console.log(`[Agent] ${msg}`);
        }
    },

    safeRun: async (scriptName, args = []) => {
        if (!scriptName || typeof scriptName !== 'string') {
            AgentUtils.safeLog('Error: Invalid script name');
            return false;
        }

        const resources = await AgentUtils.getAvailableResources();
        if (!resources.funds) {
            AgentUtils.safeLog('Error: Insufficient funds for script execution');
            return false;
        }

        try {
            AgentUtils.safeLog(`Executing script: ${scriptName}`);
            await this.runScript(scriptName);
            AgentUtils.safeLog(`Script ${scriptName} completed successfully`);
            return true;
        } catch (error) {
            AgentUtils.safeLog(`Execution error for ${scriptName}: ${error.message}`);
            return false;
        }
    },

    checkResources: async () => {
        const mem = await this.memory.getUsed();
        const funds = await this.getMoney();
        return { mem, funds };
    },

    validateEnvironment: async () => {
        try {
            const env = await this.runCommand('env');
            if (!env.includes('NETSCRIPT')) {
                throw new Error('Invalid environment');
            }
            return true;
        } catch (err) {
            throw new Error(`Environment check failed: ${err.message}`);
        }
    },

    async executeTask(task) {
        if (!task || !task.script) {
            throw new Error('Invalid task object');
        }
        const { script, args, maxRetries } = task;
        let lastError = null;

        for (let i = 0; i < maxRetries; i++) {
            AgentUtils.safeLog(`Attempt ${i + 1} for ${script}`);

            if (!AgentUtils.validateEnvironment()) {
                throw new Error('Environment validation failed');
            }

            const result = await AgentUtils.safeRun(script, args);
            if (result) return true;

            if (i < maxRetries - 1) {
                await new Promise(resolve => setTimeout(resolve, 500));
            }
        }
        throw new Error(`Max retries exceeded for ${script}`);
    }
};

const runAgentLoop = async () => {
    try {
        await AgentUtils.validateEnvironment();
        await AgentUtils.checkResources();
        while (true) {
            try {
